746: 						$subs = array_fill(0, count($allCmds), $sub);
747: 						$cmds = array_merge($cmds, array_map(array('elFinder', 'addSubToBindName'), $allCmds, $subs));
748: 					} else {
749: 						$cmds = array_merge($cmds, $allCmds);
750: 					}
751: 				} else {
752: 					$cmds[] = $_cmd;
753: 				}
754: 			}
755: 		}
756: 		$cmds = array_unique($cmds);
