758: 		foreach ($cmds as $cmd) {
759: 			if (!isset($this->listeners[$cmd])) {
760: 				$this->listeners[$cmd] = array();
761: 			}
762: 
763: 			if (is_callable($handler)) {
764: 				$this->listeners[$cmd][] = $handler;
765: 			}
766: 		}
767: 
768: 		return $this;
769: 	}
